#!/usr/bin/env python3
"""Generate the statement ledger for CATHOT Parts B and C."""
from pathlib import Path
import csv

ROOT = Path(__file__).resolve().parents[1]
rows = [
('B.1','Evaluation Fun(BG,K) -> K is a category isomorphism when G has no nontrivial homomorphisms to automorphism groups of K','Proved','Part B, B.1','','V ms.37--43','Includes empty categories and noninvertible endomorphisms.'),
('B.2','For |F| >= 8 the Schur multiplier of Alt(F) is Z/2, generated by the fixed four-letter torus class','Known','Part B, B.2','BC_DominguezSegovia2021, Eq.(35), Prop.20, Cor.21','Lead 1','Finite upper bound is an imported classical theorem; transition maps checked using a fixed generator; exact Clifford algebra check attached.'),
('B.3','For every infinite set Omega the finitary alternating group has size |Omega|, is simple and perfect, and has H_2 = Z/2','Proved','Part B, B.3','B.2','Lead 1; V ms.37','Simplicity proved with fresh-point commutator; bar complexes give filtered homology colimit with verified transition maps.'),
('B.4','A right adjoint Cat hot -> Hot exists, or K(Z/2,2) has a small Thomason--Kan envelope','Refuted','Part B, B.4','B.1; B.3','V ms.37--43; III-V companion unproved reflection block','Refutes existence of any right adjoint, not only a fully faithful one.'),
('B.5','Every group of cardinal at most lambda embeds in a nonabelian simple group of the prescribed infinite cardinal lambda','Proved','Part B, B.5','BC_HNN1949, Theorem II','Lead 1 strengthening','Explicit free-product word w=[g,t][g,t^2] and HNN relations put every h in normal closure of g; cardinal bound checked.'),
('B.6','Every group embeds in an acyclic group of cardinal max(|H|,aleph_0)','Proved','Part B, B.6','BC_BDH1980, Prop.4.1, Thm.4.2, Lem.5.4','Lead 1 strengthening','Mitosis construction and field-homology annihilation proof supplied.'),
('B.7','Every group of size at most lambda embeds in an acyclic nonabelian simple group of size lambda','Proved','Part B, B.7','B.5; B.6','Lead 1 strengthening','Alternating injective simple and acyclic envelopes; no priority claimed.'),
('B.8','For n >= 2 and every infinite lambda there is a perfect group G of size lambda with no smaller nontrivial quotient and a homology equivalence BG -> S^n','Proved','Part B, B.8','B.7','Lead 1 strengthening; S^2 test case','Iterated amalgamated doubles over acyclic simple envelopes; group need not itself be simple.'),
('B.9','Integral homology equivalences induce equivalences of derived mapping spaces into simply connected targets','Proved','Part B, B.9','BC_Lawson2019, Example 9.2','Lead 1 strengthening','Full Postnikov mapping-space argument handles infinite towers and avoids phantom-map inference.'),
('B.10','Every non-1-type receives an essential unpointed map from groups of unbounded size having no smaller nontrivial quotient','Proved','Part B, B.10','B.8; B.9','Lead 1 strengthening','Universal-cover lifting proves non-nullness for arbitrary nontrivial pi_1 action.'),
('B.11','The presheaf X -> [BX,Y] is not representable on Cat hot for any Y which is not a 1-type','Proved','Part B, B.11','B.1; B.10','V ms.37--43; Lead 2','Naturality of constant-map square handles disconnected targets and infinite component sets.'),
('C.1','Every small groupoid is local and Fun(Pi_1 X,G) -> Fun(X,G) is a category isomorphism','Proved','Part C, C.1','','Lead 2; V ms.37--43','NFun(X,G) is exactly the Kan derived simplicial mapping space.'),
('C.2','Representable homotopy types on Cat hot are exactly the 1-types; representing categories are unique up to isomorphism in Cat hot','Proved','Part C, C.2','B.11; C.1','Lead 2; V ms.37--43','Includes empty and disconnected types; specified universal element is a weak equivalence in Hot.'),
('C.3','Local categories are exactly categories isomorphic in Cat hot to a groupoid, equivalently those whose canonical groupoidification unit is an isomorphism in Cat hot','Proved','Part C, C.3','C.1; C.2','Lead 2; VII ms.136','Localness forces a 1-type; the converse from nerve 1-type alone fails.'),
('C.4','The full subcategory of local categories is reflective with reflector Pi_1 and units X -> Pi_1 X','Proved','Part C, C.4','C.1; C.3','Lead 2; V ms.37--43','This reflector inverts W_1, not merely W_infty; unit is W_infty exactly for 1-types.'),
('C.5','The local subcategory is coreflective, or contractible classifying space suffices for localness','Refuted','Part C, C.5','C.1; C.3','Lead 2; V ms.48--49','Infinite fence and discrete N source give a uniform-length obstruction; finite truncation checks attached.'),
('C.6','Every Thomason-fibrant category is local in the manuscript sense','Refuted','Part C, C.6','C.3; Thomason model structure','V ms.37--43; VII ms.136','Fibrant replacement of a category of type S^2 has a higher type and is not local.')
]
path = ROOT/'research/BC_results.csv'
with path.open('w', newline='') as f:
    writer = csv.writer(f)
    writer.writerow(['id','statement','status','where_proved','depends_on','manuscript_rows_or_pages_settled','notes'])
    writer.writerows(rows)
print(f'Wrote {len(rows)} statement rows to {path.name}')

if __name__ == '__main__':
    assert len({row[0] for row in rows}) == len(rows)
